/** @type {import('tailwindcss').Config} */

// Palettes are driven by CSS variables (resources/css/theme.css, generated by
// scripts/generate-theme.cjs) so one set of class names renders both themes.
const ACCENTS = ['emerald', 'teal', 'cyan', 'sky', 'blue', 'indigo', 'violet', 'purple', 'fuchsia', 'pink', 'rose', 'red', 'orange', 'amber', 'yellow', 'lime', 'green'];
const SHADES = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950];

const v = (name) => `rgb(var(--${name}) / <alpha-value>)`;
const palette = (name) => Object.fromEntries(SHADES.map((s) => [s, v(`${name}-${s}`)]));

export default {
    darkMode: 'class',
    content: [
        './vendor/laravel/framework/src/Illuminate/Pagination/resources/views/*.blade.php',
        './storage/framework/views/*.php',
        './resources/views/**/*.blade.php',
        './resources/js/**/*.tsx',
        './resources/js/**/*.ts',
        './resources/js/**/*.jsx',
        './resources/js/**/*.js',
    ],
    theme: {
        extend: {
            fontFamily: {
                sans: ['"Plus Jakarta Sans"', 'system-ui', '-apple-system', 'sans-serif'],
                mono: ['"JetBrains Mono"', 'monospace'],
            },
            colors: {
                slate: palette('slate'),
                white: v('white'),
                ...Object.fromEntries(ACCENTS.map((a) => [a, palette(a)])),

                // Theme-aware surfaces
                canvas: v('canvas'),
                deep: v('deep'),
                panel: v('panel'),

                // Label colours for solid accent buttons: ink adapts to the theme, paper is always white
                ink: v('ink'),
                paper: '#ffffff',
            },
            boxShadow: {
                'glow-emerald': '0 0 25px -5px rgba(16, 185, 129, 0.35)',
                'glow-cyan': '0 0 25px -5px rgba(6, 182, 212, 0.35)',
                'glow-rose': '0 0 25px -5px rgba(244, 63, 94, 0.35)',
                glass: 'var(--shadow-glass)',
            },
            backdropBlur: {
                xs: '2px',
            },
            animation: {
                'pulse-slow': 'pulse 3s cubic-bezier(0.4, 0, 0.6, 1) infinite',
                float: 'float 3s ease-in-out infinite',
                'toast-in': 'toast-in 0.25s ease-out',
            },
            keyframes: {
                float: {
                    '0%, 100%': { transform: 'translateY(0)' },
                    '50%': { transform: 'translateY(-6px)' },
                },
                'toast-in': {
                    from: { opacity: '0', transform: 'translateY(8px) scale(0.98)' },
                    to: { opacity: '1', transform: 'translateY(0) scale(1)' },
                },
            },
        },
    },
    plugins: [
        require('@tailwindcss/forms'),
    ],
};
